import{_ as t,o as e,c as i,ag as p}from"./chunks/framework.KxDd3USm.js";const u=JSON.parse('{"title":"05.8 精华题与补充题","description":"","frontmatter":{},"headers":[],"relativePath":"05-操作系统/91-精华题与补充题.md","filePath":"05-操作系统/91-精华题与补充题.md"}'),m={name:"05-操作系统/91-精华题与补充题.md"};function a(s,l,o,r,_,B){return e(),i("div",null,[...l[0]||(l[0]=[p('<h1 id="_05-8-精华题与补充题" tabindex="-1">05.8 精华题与补充题 <a class="header-anchor" href="#_05-8-精华题与补充题" aria-label="Permalink to &quot;05.8 精华题与补充题&quot;">​</a></h1><ol><li><p>【页面置换】某系统 3 个物理块，引用串为 1、3、1、2、4、3、1、4。分别求 FIFO、LRU、OPT 的缺页次数与缺页率，并用&quot;串长 − 命中数&quot;验算。</p></li><li><p>【磁盘调度】磁头当前位于 100 号磁道，正沿磁道号减小方向移动；等待访问的磁道号：90、120、55、140、30。磁盘磁道号为 0～199。求：① SSTF 的总移动道数（SSTF 不受初始方向约束）；② SCAN 的总移动道数（设定：沿当前方向移动到 0 号磁道后才折返）。</p></li><li><p>【死锁资源数】某系统 5 个进程，每个进程最多需要 3 个同类资源。① 系统至少配多少个该资源才能保证<strong>不可能</strong>死锁？② 若系统只有 10 个该资源，死锁是否可能发生？</p></li><li><p>【位示图】某文件管理系统的位示图字长 64 位，块号、字号、位号均从 0 开始编号。① 磁盘容量 512GB、物理块大小 4MB，位示图共需多少个字？② 物理块号 100000 记录在位示图的第几个字、第几位？</p></li><li><p>【页式地址变换】页面大小 2KB，页表中页 2 对应物理块 7。逻辑地址 4500 的物理地址是多少？</p></li><li><p>【周转时间】三个作业：J1 时刻 0 到达、需运行 5；J2 时刻 2 到达、需运行 2；J3 时刻 3 到达、需运行 1。单道系统下分别按 FCFS 和 SJF（非抢占）调度，求各自的平均周转时间。</p></li><li><p>【索引文件】某 UNIX 式文件系统，磁盘块大小 2KB，每个地址项占 4B，索引节点含 6 个直接地址项、1 个一级间接地址项、1 个二级间接地址项。单个文件的最大长度是多少？</p></li></ol><hr><h2 id="补充题-扩充考点专项-不破坏原题编号" tabindex="-1">补充题（扩充考点专项，不破坏原题编号） <a class="header-anchor" href="#补充题-扩充考点专项-不破坏原题编号" aria-label="Permalink to &quot;补充题（扩充考点专项，不破坏原题编号）&quot;">​</a></h2><ol><li><p>【段页式位数】某段页式存储，地址结构为段号 10 位、页号 10 位、页内地址 12 位。该系统最多支持的段数、每段内最多页数、每页大小分别约为（ ）。 A. 1024 段、1024 页、4KB B. 10 段、10 页、12KB C. 1024 段、4096 页、1KB D. 100 段、100 页、4KB</p></li><li><p>【磁盘存取时间】读一个数据块需寻道 5ms、平均旋转延迟 10ms、传输 1ms。一个文件分散存放在 100 个数据块，读取该文件大致需要（ ）。 A. 1600ms B. 160ms C. 100ms D. 16000ms</p></li><li><p>【索引定位】磁盘块 1KB、地址项 4B，索引节点含 10 个直接、1 个一级间接、1 个二级间接。文件逻辑块号 300，访问该块需读磁盘（ ）次。 A. 1 B. 2 C. 3 D. 4</p></li><li><p>【位示图从 1 编号】字长 32 位，块号、字号、位号均从 1 编号，物理块 1000 记录在位示图的（ ）。 A. 第 32 字、第 8 位 B. 第 31 字、第 8 位 C. 第 32 字、第 7 位 D. 第 31 字、第 9 位</p></li><li><p>【生产者-消费者】缓冲区容量 5，用 mutex=1、empty=5、full=0 实现，生产者正确的操作顺序是（ ）。 A. P(empty); P(mutex); 放入; V(mutex); V(full); B. P(mutex); P(empty); 放入; V(mutex); V(full); C. P(empty); 放入; P(mutex); V(full); V(mutex); D. P(full); P(mutex); 放入; V(mutex); V(empty);</p></li><li><p>【进程资源图】化简进程资源图时，某轮判断某进程可否化简，正确依据是（ ）。 A. 申请量 ≤ 该资源当前空闲量，即该进程为非阻塞进程 B. 优先让申请量最大的进程先运行 C. 优先让持有资源最少的进程先运行 D. 只要图中存在环就一定是死锁</p></li><li><p>【单双缓冲】读一块 t=2ms、处理一块 c=6ms。对 10 块数据，单缓冲总耗时为（ ），双缓冲为（ ）。 A. 80ms / 62ms B. 62ms / 80ms C. 80ms / 80ms D. 20ms / 20ms</p></li><li><p>【FCB】文件控制块（FCB）中通常<strong>不</strong>包含（ ）。 A. 文件名 B. 文件在磁盘上的物理位置 C. 文件内容 D. 存取权限</p></li><li><p>【Linux 权限】执行 <code>chmod 754</code> 后，同组用户对该文件的权限是（ ）。 A. rwx B. r-x C. r-- D. -wx</p></li><li><p>【页大小换算】页内地址占 12 位，页大小为（ ）。 A. 1KB B. 2KB C. 4KB D. 8KB</p></li></ol><hr>',6)])])}const c=t(m,[["render",a]]);export{u as __pageData,c as default};
